export type CopyKey = keyof typeof COPY;

/** Bot copy in a language with escaped values. Values in `raw` are inserted as HTML. */
export function say(locale: Locale, key: CopyKey, values: Record<string, string | number> = {}, raw: Record<string, string> = {}): string {
  const escaped = Object.fromEntries(Object.entries(values).map(([name, value]) => [name, escapeHtml(String(value))]));
  return fill(COPY[key][locale] ?? COPY[key].en, { ...escaped, ...raw });
}
/** Plain (unescaped) copy, for button labels and poll text. */
export const plain = (locale: Locale, key: CopyKey, values: Record<string, string | number> = {}) => fill(COPY[key][locale] ?? COPY[key].en, values);
